def sync(db: Session) -> None:
    have = set(db.scalars(select(ChangeLogEntry.key)))
    for key, kind, title, text, day in ENTRIES:
        if key not in have:
            db.add(ChangeLogEntry(key=key, kind=kind, title=title, text=text, released_on=day))
    db.commit()
